<?php declare(strict_types=1); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page layout editor</title>
<style>body{font:15px system-ui;background:#f5f7f5;color:#24332a;margin:0}.wrap{max-width:1100px;margin:35px auto;padding:0 20px}.toolbar,.row,.widget{background:#fff;border:1px solid #dfe6e0;border-radius:12px;padding:16px;margin:12px 0}.columns{display:grid;gap:12px}.column{min-height:80px;background:#f7faf7;border:1px dashed #afc4b5;padding:12px;border-radius:9px}.widget{margin:8px 0;padding:10px}button,select,input,textarea{font:inherit;padding:8px;border-radius:7px;border:1px solid #b9c9bd}button{background:#176b50;color:white;cursor:pointer;border:0;margin:3px}button.secondary{background:#e7eee9;color:#24332a}input,textarea{box-sizing:border-box;width:100%;margin:5px 0}textarea{min-height:80px}.actions{display:flex;flex-wrap:wrap;gap:6px;align-items:center}.widget-label{font-weight:700}</style></head><body><main class="wrap"><h1>Page layout editor</h1><p>Edit rows, column counts, widget content and ordering. Changes are saved only when you select Save layout.</p><form method="post" action="<?= e(app_url('/admin/pages/layout/save')) ?>" id="layoutForm"><?= csrf_field() ?><input type="hidden" name="page_key" value="<?= e($key) ?>"><input type="hidden" name="language_code" value="<?= e($locale) ?>"><input type="hidden" name="layout_json" id="layoutJson"><div class="toolbar actions"><button type="button" id="addRow">Add row</button><button type="submit">Save layout</button><a href="<?= e(app_url('/admin/pages')) ?>">Back to pages</a></div><div id="rows"></div></form></main>
<script>
(function(){
'use strict';
let layout=<?= json_encode(json_decode($layout,true)?:['rows'=>[]],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE) ?>;
if(!Array.isArray(layout.rows))layout={rows:[]};
const root=document.getElementById('rows'),form=document.getElementById('layoutForm');
function el(tag,text,cls){const n=document.createElement(tag);if(text!==null)n.textContent=text;if(cls)n.className=cls;return n;}
function action(label,fn,secondary){const b=el('button',label,secondary?'secondary':'');b.type='button';b.addEventListener('click',fn);return b;}
function move(items,index,offset){const next=index+offset;if(next<0||next>=items.length)return;[items[index],items[next]]=[items[next],items[index]];render();}
function render(){root.replaceChildren();layout.rows.forEach((row,ri)=>{const panel=el('section',null,'row');const tools=el('div',null,'actions');tools.append(el('strong','Row '+(ri+1)),action('Move up',()=>move(layout.rows,ri,-1),true),action('Move down',()=>move(layout.rows,ri,1),true),action('Remove row',()=>{layout.rows.splice(ri,1);render();},true));const count=el('select');for(let i=1;i<=6;i++){const option=el('option',i+' column'+(i===1?'':'s'));option.value=i;option.selected=row.columns.length===i;count.append(option);}count.addEventListener('change',()=>{const n=Number(count.value);while(row.columns.length<n)row.columns.push([]);row.columns.length=n;render();});tools.append(count);panel.append(tools);const columns=el('div',null,'columns');columns.style.gridTemplateColumns='repeat('+row.columns.length+',minmax(0,1fr))';row.columns.forEach((widgets,ci)=>{const col=el('div',null,'column');col.append(el('strong','Column '+(ci+1)));widgets.forEach((widget,wi)=>{const box=el('div',null,'widget'),buttons=el('div',null,'actions');buttons.append(el('span',widget.type,'widget-label'),action('↑',()=>move(widgets,wi,-1),true),action('↓',()=>move(widgets,wi,1),true),action('Remove',()=>{widgets.splice(wi,1);render();},true));box.append(buttons);for(const field of (widget.type==='banner'?['eyebrow','text','description','url','alt','button_text','button_url']:widget.type==='button'?['text','url']:widget.type==='image'?['url','alt']:widget.type==='spacer'?['height']:['text'])){const input=field==='text'&&widget.type==='text'?el('textarea'):el('input');input.placeholder=field;input.value=widget[field]||'';input.addEventListener('input',()=>{widget[field]=input.value;});box.append(input);}col.append(box);});const add=el('select');for(const type of ['heading','text','image','banner','button','spacer']){const o=el('option',type);o.value=type;add.append(o);}col.append(add,action('Add widget',()=>{widgets.push({type:add.value,text:'',url:'',alt:'',height:'40'});render();}));columns.append(col);});panel.append(columns);root.append(panel);});}
document.getElementById('addRow').addEventListener('click',()=>{layout.rows.push({columns:[[]]});render();});
form.addEventListener('submit',()=>{document.getElementById('layoutJson').value=JSON.stringify(layout);});render();
})();
</script></body></html>
